const apiKey = $env.NAVITIA_API_KEY;
const encoded = Buffer.from(apiKey + ':').toString('base64');
const cities = [
  { city: 'Paris',     region_id: 'fr-idf' },
  { city: 'Lille',     region_id: 'fr-hdf' }
];
return cities.map(c => ({ json: { ...c, auth_header: 'Basic ' + encoded } }));

const city = $('Prepare Cities').item.json.city;
const region_id = $('Prepare Cities').item.json.region_id;
const disruptions = ($json.disruptions) || [];
const blocking = disruptions.filter(d => d.severity && d.severity.effect === 'NO_SERVICE').length;
const reduced  = disruptions.filter(d => d.severity && d.severity.effect === 'REDUCED_SERVICE').length;
const total = disruptions.length;
let network_status = 'NORMAL';
if (blocking > 0) network_status = 'DISRUPTED';
else if (reduced > 0 || total > 3) network_status = 'REDUCED';
const most_severe = disruptions.find(d => d.severity && d.severity.effect === 'NO_SERVICE') || disruptions[0];
const most_severe_message = (most_severe && most_severe.messages && most_severe.messages[0])
  ? most_severe.messages[0].text : null;
return [{ json: { city, region_id, total_disruptions: total, blocking_disruptions: blocking, network_status, most_severe_message, raw_payload: $json } }];
